/**
 * The handshake a page of the layout 3 release presents for a fresh replica
 * (`createYServerLayoutUpgrade().handshake`): it reads layout 3 only and seeds layout 3.
 */
export const LAYOUT3_RELEASE_HANDSHAKE = {
  v: 1,
  generation: null,
  material: false,
  layouts: [3, 3],
  seed: 3,
} as const;

/** One of those states, decoded. */
export function layout3Note(name: keyof typeof LAYOUT3_NOTES): Uint8Array {
  const binary = atob(LAYOUT3_NOTES[name]);
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    out[i] = binary.charCodeAt(i);
  }
  return out;
}
